{{ (async () => {
  try {
    if (appsmith.store.editingSessionId) {
      await updateScreeningSession.run();
      storeValue('editingSessionId', null);
      storeValue('editingSessionStatus', null);
    } else {
      const matchResult = await createCandidateJobMatch.run();
      const matchId = matchResult?.[0]?.id ?? matchResult?.id;
      if (!matchId) throw new Error('Failed to create match');
      storeValue('activeMatchId', matchId);

      const sessionResult = await createScreeningSession.run();
      const sessionId = sessionResult?.[0]?.id ?? sessionResult?.id;
      if (!sessionId) throw new Error('Failed to create session');
      storeValue('activeSessionId', sessionId);

      showAlert('Generating questions — this takes 15-20 seconds...', 'info');
      await generateScreeningQuestions.run();
      showAlert('Questions ready', 'success');
    }

    await getUpcomingScreenings.run();
    closeModal('modalScheduleScreening');
    closeModal('modalFindCandidates');
  } catch (e) {
    showAlert('Failed: ' + (e?.message ?? 'unknown'), 'error');
  }
})() }}

