export default {
	// === COLOUR PALETTE (single source of truth) ===
	// Change these and every widget bound to Theme updates instantly.
	colors: {
		// Brand
		navy:        "#0F1B2D",
		navyDeep:    "#0A1320",
		surface1:    "#131F33",
		surface2:    "#1A2841",
		gold:        "#C9A961",
		goldHover:   "#B8983F",

		// Text
		textOnDark:  "#FFFFFF",
		textMuted:   "#94A3B8",
		textDim:     "#64748B",

		// Alert states (lightened from previous dark tones for readability)
		alertRed:    "#B91C1C",
		alertAmber:  "#C2410C",
		alertRedText:   "#FECACA",
		alertAmberText: "#FED7AA",

		// Borders
		hairline:    "rgba(255, 255, 255, 0.08)"
	},

	// === TILE STYLE HELPERS ===
	// Returns the background colour based on a numeric value and tile type.
	// Default tiles always navy. Alert tiles go coloured when value > 0.
	tileBackground: (value, type) => {
		const v = value ?? 0;
		if (type === "overdue")  return v > 0 ? "#B91C1C" : "#0F1B2D";
		if (type === "dueToday") return v > 0 ? "#C2410C" : "#0F1B2D";
		return "#0F1B2D";
	},

	// Subtitle text colour matches the tile background mood
	tileSubtitleColor: (value, type) => {
		const v = value ?? 0;
		if (type === "overdue"  && v > 0) return "#FECACA";
		if (type === "dueToday" && v > 0) return "#FED7AA";
		return "#94A3B8";
	},

	// === WEEK-OVER-WEEK DELTA FORMATTER ===
	// Pass this week's value and last week's value, get a clean string.
	weekDelta: (tw, lw) => {
		const thisWk = tw ?? 0;
		const lastWk = lw ?? 0;
		if (lastWk === 0 && thisWk === 0) return "no change this week";
		if (lastWk === 0) return `+${thisWk} new this week`;
		const pct = Math.round(((thisWk - lastWk) / lastWk) * 100);
		if (pct === 0) return "no change vs last week";
		return `${pct > 0 ? "+" : ""}${pct}% vs last week`;
	}
}

