export default {
	// === USER STATE HELPERS ===
	current: () => {
		if (typeof fetchMyUser !== 'undefined' && fetchMyUser?.data?.[0]) {
			return fetchMyUser.data[0];
		}
		if (typeof ensureMyUser !== 'undefined' && ensureUser?.data?.[0]) {
			return ensureUser.data[0];
		}
		if (typeof ensureUser !== 'undefined' && ensureUser?.data?.[0]) {
			return ensureUser.data[0];
		}
		return null;
	},

	isAdmin: () => {
		const u = Auth.current();
		return u?.role === 'admin';
	},

	profileComplete: () => {
		const u = Auth.current();
		return !!u?.profile_completed_at;
	},

	showProfileBanner: () => {
		const u = Auth.current();
		return u !== null && !u.profile_completed_at;
	},

	// === OWNERSHIP HELPERS ===
	// Compares claimed_by email directly (NOT claim_status — that field gets transformed
	// by the table column display value to show the recruiter's display name).
	ownsSelectedJob: () => {
		const row = typeof tableHotJobs !== 'undefined' ? tableHotJobs.selectedRow : null;
		if (!row || !row.id) return false;
		return row.claimed_by === appsmith.user.email;
	},

	selectedJobUnclaimed: () => {
		const row = typeof tableHotJobs !== 'undefined' ? tableHotJobs.selectedRow : null;
		if (!row || !row.id) return false;
		return !row.claimed_by;
	},

	selectedJobClaimedByOther: () => {
		const row = typeof tableHotJobs !== 'undefined' ? tableHotJobs.selectedRow : null;
		if (!row || !row.id) return false;
		return !!row.claimed_by && row.claimed_by !== appsmith.user.email;
	}
}

