export default {
	// === USER STATE HELPERS ===
	// Returns the current user record from getMyProfile.
	// Falls back to null if not loaded yet.
	current: () => {
		// Try Settings page query first
		if (typeof getMyProfile !== 'undefined' && getMyProfile?.data?.[0]) {
			return getMyProfile.data[0];
		}
		// Fall back to ensureUser query if that's what's on this page
		if (typeof ensureMyUser !== 'undefined' && ensureMyUser?.data?.[0]) {
			return ensureMyUser.data[0];
		}
		if (typeof ensureUser !== 'undefined' && ensureUser?.data?.[0]) {
			return ensureUser.data[0];
		}
		return null;
	},

	// True if the current user is an admin.
	// Used for hiding admin-only UI later.
	isAdmin: () => {
		const u = Auth.current();
		return u?.role === 'admin';
	},

	// True if the user has filled in their profile.
	// profile_completed_at is set on first save of the Settings page.
	profileComplete: () => {
		const u = Auth.current();
		return !!u?.profile_completed_at;
	},

	// True when we should show the "complete your profile" banner.
	// Only fires once user data has loaded — avoids flash on initial render.
	showProfileBanner: () => {
		const u = Auth.current();
		return u !== null && !u.profile_completed_at;
	}
}

